window.ScripturaLexicons.LSJ.rowsHtml += "<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n51\" data-source=\"LSJ\" data-search=\"ἄβαξ placa; tabuleiro; ábaco n51\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἄβαξ</td><td>Substantivo masculino</td><td>placa; tabuleiro; ábaco</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n52\" data-source=\"LSJ\" data-search=\"ἀβάπτιστος não submersível; não encharcado n52\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἀβάπτιστος</td><td>Adjetivo (-ον)</td><td>não submersível; não encharcado</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n53\" data-source=\"LSJ\" data-search=\"ἄβαπτος ferro não temperado n53\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἄβαπτος</td><td>Adjetivo (-ον)</td><td>ferro não temperado</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n";
window.ScripturaLexicons.LSJ.cardsHtml += "<article id=\"entry-lsj-n51\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n51\" data-lsj-ordinal=\"56\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄβαξ\" data-meanings=\"placa; tabuleiro; ábaco\">ἄβαξ</h1><div class=\"entry-meta\"><span>Substantivo masculino</span><span class=\"separator\">·</span><span>LSJ · artigo 56</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἄβαξ</strong> [ᾰ], genitivo <span class='greek'>-ᾰκος</span>, masculino. <strong>I.</strong> Placa, prancha ou tabuleiro. <strong>1a.</strong> Tabuleiro de cálculo, usado também para contar votos (Aristóteles, <em>Constituição de Atenas</em> 69.1). <strong>1b.</strong> Tabuleiro coberto de areia ou pó para desenhar diagramas geométricos (Sexto Empírico, <em>M.</em> 9.282; Jâmblico, <em>Protréptico</em> 34; <em>VP</em> 5.22, no plural). <strong>2.</strong> Tabuleiro de dados (Carístio 3). <strong>3.</strong> Aparador, mesa de apoio (Amônio, <em>Diff.</em> 1). <strong>4.</strong> Travessa ou prato (Cratino 86; <em>BCH</em> 29.510, Delos, século III a.C.). <strong>II.</strong> Na forma latina <em>abacus</em>: placa sobre o capitel de uma coluna (Vitrúvio 3.5.5); <strong>II.2.</strong> placa de mármore para revestimento de parede (Vitrúvio 7.3.10). <strong>III.</strong> Ver <span class='greek'>ἀβακής</span>.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI auxiliar Perseus/Tufts–LSJLogeion, <code>greatscott02.xml</code>, <code>orig_id=n51</code>. Tradução de trabalho; colação com Oxford 1940 e revisão filológica independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n52\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n52\" data-lsj-ordinal=\"57\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβάπτιστος\" data-meanings=\"não submersível; não encharcado\">ἀβάπτιστος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον)</span><span class=\"separator\">·</span><span>LSJ · artigo 57</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβάπτιστος, -ον</strong> (de <span class='greek'>βαπτίζω</span>). <strong>I.</strong> Que não deve ser mergulhado; que não afunda. <span class='greek'>ἀ. ἅλμας</span>, dito de uma rede (Píndaro, <em>Píticas</em> 2.80); de um navio (<span class='greek'>ναῦς</span>; <em>EM</em> 811.26). Dito de um trépano (<span class='greek'>τρύπανον</span>): munido de limitador para impedir penetração excessiva (Galeno 10.447). <strong>II.</strong> Não embebido em bebida alcoólica, não encharcado de vinho (Plutarco, <em>QConv.</em> 2.686b).</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI auxiliar Perseus/Tufts–LSJLogeion, <code>greatscott02.xml</code>, <code>orig_id=n52</code>. Tradução de trabalho; colação com Oxford 1940 e revisão filológica independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n53\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n53\" data-lsj-ordinal=\"58\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄβαπτος\" data-meanings=\"ferro não temperado\">ἄβαπτος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον)</span><span class=\"separator\">·</span><span>LSJ · artigo 58</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἄβαπτος, -ον</strong> (de <span class='greek'>βάπτω</span>): dito do ferro, «não temperado» (Hesíquio; Suda).</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI auxiliar Perseus/Tufts–LSJLogeion, <code>greatscott02.xml</code>, <code>orig_id=n53</code>. Tradução de trabalho; colação com Oxford 1940 e revisão filológica independente pendentes.</p></section></article>\n";
