window.ScripturaLexicons.LSJ.rowsHtml += "<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n54\" data-source=\"LSJ\" data-search=\"ἀβαρβάριστος sem barbarismos n54\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἀβαρβάριστος</td><td>Adjetivo (-ον)</td><td>sem barbarismos</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n55\" data-source=\"LSJ\" data-search=\"ἀβαρής sem peso; leve; não oneroso; não ofensivo n55\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἀβαρής</td><td>Adjetivo (-ές)</td><td>sem peso; leve; não oneroso; não ofensivo</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n";
window.ScripturaLexicons.LSJ.cardsHtml += "<article id=\"entry-lsj-n54\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n54\" data-lsj-ordinal=\"59\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβαρβάριστος\" data-meanings=\"sem barbarismos\">ἀβαρβάριστος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον)</span><span class=\"separator\">·</span><span>LSJ · artigo 59</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβαρβάριστος, -ον</strong>: «sem barbarismos», <em>Lexicon Vindobonense</em> 294. <strong>Advérbio:</strong> <span class=\"greek\">ἀβαρβαρίστως</span>, <em>Etimologicum Magnum</em> 331.37. A fonte registra <span class=\"greek\">ἀβάρβαρος</span> como falsa leitura em lugar de <span class=\"greek\">ἀβόρβορος</span> (ver este verbete).</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n54. Tradução de trabalho; revisão independente e colação com o impresso pendentes.</p></section></article>\n<article id=\"entry-lsj-n55\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n55\" data-lsj-ordinal=\"60\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβαρής\" data-meanings=\"sem peso; leve; não oneroso; não ofensivo\">ἀβαρής</h1><div class=\"entry-meta\"><span>Adjetivo (-ές)</span><span class=\"separator\">·</span><span>LSJ · artigo 60</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβαρής, -ές</strong> (de <span class=\"greek\">βάρος</span>). <strong>I.</strong> «Sem peso», Aristóteles, <em>De caelo</em> 277b19; <span class=\"greek\">ἀβαρῆ εἶναι ἀέρα καὶ πῦρ</span>, «serem o ar e o fogo sem peso», Zenão estoico 1.27; cf. Crisipo estoico 2.143 e Plotino 6.9.9. «Leve», de <span class=\"greek\">γῆ</span> («terra»), <em>Antologia Palatina</em> 7.461 (Meleagro); figuradamente, «assunto leve», <em>Comica Adespota</em> 158; «franqueza suave e leve», Plutarco, <em>De adulatore</em> 59c; do pulso, Arquígenes apud Galeno 8.651. <strong>II.</strong> «Não ofensivo», de odores, Areteu, <em>CA</em> 2.3; de pessoas, «não oneroso», <span class=\"greek\">ἀ. ἑαυτὸν τηρεῖν, παρέχειν</span>, 2 Coríntios 11.9; <em>CIG</em> 5361.15 (Berenice). <strong>Advérbio:</strong> <span class=\"greek\">ἀβαρῶς</span>, «sem causar ofensa», Simplício, <em>in Epictetum</em> p. 85 D; «sem se ofender», ibid. p. 88 D.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n55. Tradução de trabalho; revisão independente e colação com o impresso pendentes.</p></section></article>\n";

