window.ScripturaLexicons.LSJ.rowsHtml += "<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n56\" data-source=\"LSJ\" data-search=\"ἄβαρις sem barco; homem de terra; glosas de Hesíquio n56\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἄβαρις</td><td>Glosa; conjunto de formas associadas</td><td>sem barco; homem de terra; glosas de Hesíquio</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n57\" data-source=\"LSJ\" data-search=\"ἀβασάνιστος não torturado; não examinado; sem exame n57\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἀβασάνιστος</td><td>Adjetivo (-ον); advérbio</td><td>não torturado; não examinado; sem exame</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-lsj-n58\" data-source=\"LSJ\" data-search=\"ἀβασίλευτος sem rei; não governado por rei; livre de governo n58\" tabindex=\"0\"><td class=\"table-lemma greek\" lang=\"grc\">ἀβασίλευτος</td><td>Adjetivo (-ον)</td><td>sem rei; não governado por rei; livre de governo</td><td><span class=\"source-pill\">LSJ</span></td></tr>\n";
window.ScripturaLexicons.LSJ.cardsHtml += "<article id=\"entry-lsj-n56\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n56\" data-lsj-ordinal=\"61\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄβαρις\" data-meanings=\"sem barco; homem de terra; glosas de Hesíquio\">ἄβαρις</h1><div class=\"entry-meta\"><span>Glosa; conjunto de formas associadas</span><span class=\"separator\">·</span><span>LSJ · artigo 61</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἄβαρις</strong> (relacionado a <span class=\"greek\">βᾶρις</span>): «sem barco; homem de terra», Hesíquio. O artigo reúne ainda as glosas: <span class=\"greek\">ἀβαριστάν</span> = <span class=\"greek\">γυναικιζομένην</span> («tratada como mulher; efeminada», cipriota); <span class=\"greek\">ἀβαρκνᾷ</span> = <span class=\"greek\">κομᾶ</span> («tem cabelos longos», macedônio); <span class=\"greek\">ἄβαρκνα</span> = <span class=\"greek\">λιμός</span> («fome»); <span class=\"greek\">ἀβαρλεῖται</span> = <span class=\"greek\">ταράσσεται, κροτεῖ</span> («agita-se; bate, faz ruído»); <span class=\"greek\">ἀβάρνου</span> = <span class=\"greek\">στένε</span> («geme»); <span class=\"greek\">ἀβαρταί</span> = <span class=\"greek\">πτηναί</span> («aladas», cipriota); <span class=\"greek\">ἀβαρύ</span> = <span class=\"greek\">ὀρίγανον</span> («orégano», macedônio); <span class=\"greek\">ἀβάς</span> = <span class=\"greek\">εὐήθης;</span> («ingênuo?», interpretação incerta) ou «doença sagrada» (<span class=\"greek\">ἱερὰ νόσος</span>, tarentino); <span class=\"greek\">ἀβάσαι</span> = <span class=\"greek\">ἀριστῆσαι, καὶ ἀρθῆναι</span> («tomar a refeição matinal e ser levantado»). Todas são atribuídas a Hesíquio; não foram contadas como artigos independentes.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n56. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n57\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n57\" data-lsj-ordinal=\"62\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβασάνιστος\" data-meanings=\"não torturado; não examinado; sem exame\">ἀβασάνιστος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον); advérbio</span><span class=\"separator\">·</span><span>LSJ · artigo 62</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβασάνιστος, -ον.</strong> <strong>I.</strong> «Não torturado»: <span class=\"greek\">ἀ. θνῄσκειν</span>, «morrer sem tortura», Josefo, <em>Guerra Judaica</em> 1.32.3; cf. Plutarco, <em>Aetia Graeca</em> 275c. <span class=\"greek\">κημοῖς ὑπερῴαν ἀ.</span>, «palato não atormentado por focinheiras», Eliano, <em>De natura animalium</em> 13.9. <strong>Advérbio:</strong> <span class=\"greek\">ἀβασανίστως</span>, «sem dor», como em «olhar para o sol», Eliano, <em>De natura animalium</em> 10.14. <strong>II.</strong> «Não testado; não investigado; não examinado»: <span class=\"greek\">ἀ. τι ἐᾶσαι</span>, «deixar algo sem exame», Antifonte 1.13; <span class=\"greek\">ἀπολιπεῖν</span>, Políbio 4.75.3; <span class=\"greek\">παραλείπειν</span>, Plutarco, <em>De adulatore</em> 59c. <strong>Advérbio:</strong> «sem o devido exame», Tucídides 1.20; Plutarco, <em>De audiendis poetis</em> 28b.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n57. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n58\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n58\" data-lsj-ordinal=\"63\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβασίλευτος\" data-meanings=\"sem rei; não governado por rei; livre de governo\">ἀβασίλευτος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον)</span><span class=\"separator\">·</span><span>LSJ · artigo 63</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβασίλευτος, -ον.</strong> «Não governado por rei; sem rei», Tucídides 2.80; Xenofonte, <em>Helênicas</em> 5.2.17. Em sentido geral, «livre de governo ou domínio», Plutarco, <em>Adversus Colotem</em> 1125d; Artemidoro 1.8.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n58. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n";

