window.ScripturaLexicons.LSJ.cardsHtml += "<article id=\"entry-lsj-n59\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n59\" data-lsj-ordinal=\"64\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβασκάνιστος\" data-meanings=\"livre de malícia; leitura incerta\">ἀβασκάνιστος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον)</span><span class=\"separator\">·</span><span>LSJ · artigo 64</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβασκάνιστος, -ον.</strong> «Livre de malícia», Plutarco, <em>Amatorius</em> 755d. A fonte observa que <em>talvez</em> se deva ler <span class=\"greek\">ἀβασάν-</span> em lugar desta forma; a conjectura não foi adotada como texto certo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n59. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n60\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n60\" data-lsj-ordinal=\"65\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβάσκανος\" data-meanings=\"sem inveja; imparcial; livre de preconceito\">ἀβάσκανος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον); advérbio</span><span class=\"separator\">·</span><span>LSJ · artigo 65</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβάσκανος, -ον</strong> (de <span class=\"greek\">βασκαίνω</span>). «Livre de inveja», Teles p. 56.1 H.; substantivado, <span class=\"greek\">τὸ ἀ.</span>, Fílon 1.252. «Imparcial; livre de preconceito», de <span class=\"greek\">μάρτυς</span>, «testemunha», Josefo, <em>Guerra Judaica</em> 1.9.4. <strong>Advérbio:</strong> <span class=\"greek\">ἀβασκάνως</span>, Marco Aurélio 1.16.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n60. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n<article id=\"entry-lsj-n61\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"LSJ\" data-lsj-orig-id=\"n61\" data-lsj-ordinal=\"66\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀβάσκαντος\" data-meanings=\"protegido de encantamentos; amuleto protetor; inofensivo\">ἀβάσκαντος</h1><div class=\"entry-meta\"><span>Adjetivo (-ον); advérbio</span><span class=\"separator\">·</span><span>LSJ · artigo 66</span></div></div><div class=\"source-tag\">LSJ</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa do artigo</div><p class=\"entry-text\"><strong>ἀβάσκαντος, -ον.</strong> <strong>I.</strong> «Protegido contra encantamentos; livre de dano», <em>CIG</em> 5053 e 5119 (Núbia); <em>Cat.Cod.Astr.</em> 7.234; especialmente de crianças, <em>BGU</em> 8.11 e outros papiros; <em>P.Oxy.</em> 300 (século I d.C.). Em sentido ativo, «que serve de encanto ou proteção contra feitiçaria», <span class=\"greek\">ἀ. ἀνθρώποις καὶ ζῴοις</span>, «protetor de pessoas e animais», <em>variante de leitura</em> em Dioscórides 3.91. <strong>Advérbio:</strong> <span class=\"greek\">ἀβασκάντως</span>, com <span class=\"greek\">ὑγιαίνειν</span>, «gozar de saúde sem malefício», <em>P.Oxy.</em> 292 (século I d.C.); cf. <em>Antologia Palatina</em> 11.267. <strong>II.</strong> Em sentido ativo, «que não causa dano; inofensivo», <em>PMag.Leid.W.</em> 18.7.</p></section><section class=\"entry-section\"><div class=\"section-title\">Proveniência e estado editorial</div><p class=\"entry-text\">LSJ, transcrição TEI Perseus/Tufts–LSJLogeion, greatscott02.xml, orig_id n61. Tradução de trabalho; colação impressa e revisão independente pendentes.</p></section></article>\n";

